        /// <summary>Interactive per-game optimizer: shows a console file picker and
        /// applies or undoes GPU preference, fullscreen optimizations and CPU priority
        /// for the picked game. Runs with delayed expansion (cmd /v:on /c).
        internal static readonly string[] GameOptimizer = new[]
        {
            @"cls & echo Select The Game Location & set ""dialog=about:<input type=file id=FILE><script>FILE.click();new ActiveXObject"" & set ""dialog=!dialog!('Scripting.FileSystemObject').GetStandardStream(1).WriteLine(FILE.value);"" & set ""dialog=!dialog!close();resizeTo(0,0);</script>"" & for /f ""tokens=* delims="" %p in ('mshta.exe !dialog!') do set ""file=%p"" & if not ""!file!""=="""" (cls & for %F in (""!file!"") do ((reg query ""HKCU\Software\Microsoft\Windows NT\CurrentVersion\AppCompatFlags\Layers"" /v ""!file!"" >nul 2>&1 && (reg delete ""HKCU\Software\Microsoft\DirectX\UserGpuPreferences"" /v ""!file!"" /f & reg delete ""HKCU\Software\Microsoft\Windows NT\CurrentVersion\AppCompatFlags\Layers"" /v ""!file!"" /f & reg delete ""HKLM\Software\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\%~nxF\PerfOptions"" /v ""CpuPriorityClass"" /f & echo Undo Game Optimizations)) || (reg add ""HKCU\Software\Microsoft\DirectX\UserGpuPreferences"" /v ""!file!"" /t REG_SZ /d ""GpuPreference=2;"" /f & reg add ""HKCU\Software\Microsoft\Windows NT\CurrentVersion\AppCompatFlags\Layers"" /v ""!file!"" /t REG_SZ /d ""~ DISABLEDXMAXIMIZEDWINDOWEDMODE"" /f & reg add ""HKLM\Software\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\%~nxF\PerfOptions"" /v ""CpuPriorityClass"" /t REG_DWORD /d ""3"" /f & echo GPU High Performance & echo Disable Fullscreen Optimizations & echo CPU High Class)) >nul 2>&1)"
        };

