        /// <summary>Command chunks of the RAM profile for the given size (GB);
        /// used by the RAM slider card on the RAM page.</summary>
        internal static IReadOnlyList<string> RamProfile(int gb) => gb switch
        {
            4 => Ram4,
            8 => Ram8,
            10 => Ram10,
            12 => Ram12,
            16 => Ram16,
            20 => Ram20,
            24 => Ram24,
            32 => Ram32,
            64 => Ram64,
            _ => Ram8,
        };

        /// <summary>Network MTU & DNS Tuner: Sets MTU to 1500 and DNS to Cloudflare.</summary>
        internal static readonly string[] DnsMtuTuner = new[]
        {
            @"for /f ""skip=3 tokens=4"" %i in ('netsh interface ipv4 show interfaces') do netsh interface ipv4 set subinterface ""%i"" mtu=1500 store=persistent",
            @"for /f ""skip=3 tokens=4"" %i in ('netsh interface ipv4 show interfaces') do netsh interface ipv4 set dnsservers ""%i"" static 1.1.1.1 primary",
            @"for /f ""skip=3 tokens=4"" %i in ('netsh interface ipv4 show interfaces') do netsh interface ipv4 add dnsservers ""%i"" 1.0.0.1 index=2"
        };

        internal static readonly string[] DnsMtuTunerRevert = new[]
        {
            @"for /f ""skip=3 tokens=4"" %i in ('netsh interface ipv4 show interfaces') do netsh interface ipv4 set dnsservers ""%i"" dhcp"
        };

