        // ---------------- Hand-written command tweaks ----------------

        /// <summary>Network latency: disables Nagle's algorithm (TCPNoDelay +
        /// TcpAckFrequency = 1) on every network interface and removes the
        /// multimedia network throttling.</summary>
        internal static readonly string[] NetworkLatency = new[]
        {
            @"for /f %g in ('reg query ""HKLM\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces"" ^| findstr ""{""') do (Reg.exe add ""%g"" /v ""TcpAckFrequency"" /t REG_DWORD /d ""1"" /f & Reg.exe add ""%g"" /v ""TCPNoDelay"" /t REG_DWORD /d ""1"" /f)",
            @"Reg.exe add ""HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile"" /v ""NetworkThrottlingIndex"" /t REG_DWORD /d ""4294967295"" /f",
        };

        /// <summary>Restores Nagle's algorithm defaults (values removed) and
        /// the default network throttling index (10).</summary>
        internal static readonly string[] NetworkLatencyRevert = new[]
        {
            @"for /f %g in ('reg query ""HKLM\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters\Interfaces"" ^| findstr ""{""') do (Reg.exe delete ""%g"" /v ""TcpAckFrequency"" /f >nul 2>&1 & Reg.exe delete ""%g"" /v ""TCPNoDelay"" /f >nul 2>&1)",
            @"Reg.exe add ""HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile"" /v ""NetworkThrottlingIndex"" /t REG_DWORD /d ""10"" /f",
        };

        /// <summary>Turns off "allow the computer to turn off this device" on
        /// every physical network adapter (PnPCapabilities = 24) so the NIC
        /// never sleeps mid-game.</summary>
        internal static readonly string[] NicPowerOff = new[]
        {
            @"for /f ""tokens=*"" %k in ('reg query ""HKLM\SYSTEM\CurrentControlSet\Control\Class\{4d36e972-e325-11ce-bfc1-08002be10318}"" /s /f ""DriverDesc"" ^| findstr /i ""HKEY""') do Reg.exe add ""%k"" /v ""PnPCapabilities"" /t REG_DWORD /d ""24"" /f",
        };

        /// <summary>Restores the adapter power management default.</summary>
        internal static readonly string[] NicPowerRevert = new[]
        {
            @"for /f ""tokens=*"" %k in ('reg query ""HKLM\SYSTEM\CurrentControlSet\Control\Class\{4d36e972-e325-11ce-bfc1-08002be10318}"" /s /f ""DriverDesc"" ^| findstr /i ""HKEY""') do Reg.exe add ""%k"" /v ""PnPCapabilities"" /t REG_DWORD /d ""0"" /f",
        };

        /// <summary>Activates the hidden Ultimate Performance power plan. The
        /// plan is duplicated once and the created scheme GUID is remembered
        /// under HKCU\Software\OptiPulse, so re-applying never stacks
        /// duplicate plans.</summary>
        internal static readonly string[] UltimatePerformance = new[]
        {
            @"reg query ""HKCU\Software\OptiPulse"" /v UltimatePlanGuid >nul 2>&1 && (for /f ""tokens=3"" %g in ('reg query ""HKCU\Software\OptiPulse"" /v UltimatePlanGuid ^| findstr ""UltimatePlanGuid""') do powercfg /setactive %g) || (for /f ""tokens=4"" %g in ('powercfg -duplicatescheme e9a42b02-d5df-448d-aa00-03f14749eb61') do (powercfg /setactive %g & Reg.exe add ""HKCU\Software\OptiPulse"" /v ""UltimatePlanGuid"" /t REG_SZ /d ""%g"" /f))",
        };

        /// <summary>Switches back to the Balanced plan, removes the duplicated
        /// Ultimate Performance scheme and clears the stored marker.</summary>
        internal static readonly string[] UltimatePerformanceRevert = new[]
        {
            @"powercfg /setactive SCHEME_BALANCED",
            @"for /f ""tokens=3"" %g in ('reg query ""HKCU\Software\OptiPulse"" /v UltimatePlanGuid 2^>nul ^| findstr ""UltimatePlanGuid""') do powercfg /delete %g >nul 2>&1",
            @"Reg.exe delete ""HKCU\Software\OptiPulse"" /v ""UltimatePlanGuid"" /f >nul 2>&1 & exit /b 0",
        };

